  vez:{article:"la",pos:"NF",chinese:"次；回；次数；时机",definitionEs:"Cada ocurrencia de un hecho.",examples:[{source:"dictionary",spanish:"Esta es la primera vez que viajo en avión.",chinese:"这是我第一次坐飞机。"},{source:"dictionary",spanish:"¿Puedes repetirlo otra vez, por favor?",chinese:"请你再说一遍好吗？"},{source:"dictionary",spanish:"Cada vez que la veo, está sonriendo.",chinese:"我每次见到她，她都在微笑。"}]},
  gente:{article:"la",pos:"NF",chinese:"人们；人群；民众",definitionEs:"Conjunto de personas.",examples:[{source:"dictionary",spanish:"Hay mucha gente en el centro comercial los sábados.",chinese:"周六购物中心有很多人。"},{source:"dictionary",spanish:"La gente de este pueblo es muy amable con los visitantes.",chinese:"这个镇上的人们对游客很友好。"},{source:"dictionary",spanish:"Me gusta observar a la gente cuando estoy en un parque.",chinese:"我在公园时喜欢观察人们。"}]},
  calle:{article:"la",pos:"NF",chinese:"街道；马路；道路",definitionEs:"Vía urbana.",examples:[{source:"dictionary",spanish:"Vivo en una calle tranquila cerca del parque.",chinese:"我住在公园附近一条安静的街道上。"},{source:"dictionary",spanish:"Los niños juegan en la calle después de la escuela.",chinese:"孩子们放学后在街上玩耍。"},{source:"dictionary",spanish:"La biblioteca está al final de esta calle, a la derecha.",chinese:"图书馆在这条街的尽头，右边。"}]},
  ciudad:{article:"la",pos:"NF",chinese:"城市；都市；市区",definitionEs:"Población grande.",examples:[{source:"dictionary",spanish:"Madrid es una ciudad llena de historia y cultura.",chinese:"马德里是一座充满历史和文化的城市。"},{source:"dictionary",spanish:"Prefiero vivir en la ciudad porque hay más oportunidades de trabajo.",chinese:"我更喜欢住在城市，因为有更多工作机会。"},{source:"dictionary",spanish:"La ciudad donde nací está cerca del mar.",chinese:"我出生的城市靠近大海。"}]},
  noche:{article:"la",pos:"NF",chinese:"夜晚；晚上；夜间",definitionEs:"Período sin luz solar.",examples:[{source:"dictionary",spanish:"Me gusta leer un libro antes de dormir por la noche.",chinese:"我喜欢晚上睡觉前看会儿书。"},{source:"dictionary",spanish:"El sábado por la noche vamos a cenar fuera con amigos.",chinese:"周六晚上我们要和朋友出去吃晚饭。"},{source:"dictionary",spanish:"La ciudad es muy bonita de noche con todas las luces.",chinese:"城市夜晚灯火通明，非常美丽。"}]},
