// 词形还原 + 词典查找
function lemmatize(word: string): string[] {
  const c: string[] = [word]
  if (/os$/.test(word)) c.push(word.replace(/os$/, "o"))
  if (/as$/.test(word)) c.push(word.replace(/as$/, "a"))
  if (/ces$/.test(word)) c.push(word.replace(/ces$/, "z"))
  if (/[^c]es$/.test(word)) c.push(word.replace(/es$/, ""))
  if (/a$/.test(word)) c.push(word.replace(/a$/, "o")) // 形容词阴性 → 阳性
  return [...new Set(c)]
}

// 去重音（含 ñ→n、ü→u 等组合符号）：用于「漏写重音」的兜底匹配
function stripAccents(s: string): string {
  return s.normalize("NFD").replace(/[\u0300-\u036f]/g, "")
}

// 去重音索引（懒构建）：去重音形式 → 词典键（首个命中优先）
let deaccentIndex: Record<string, string> | null = null
function getDeaccentIndex(): Record<string, string> {
  if (!deaccentIndex) {
    deaccentIndex = {}
    for (const key of Object.keys(DICT)) {
      const d = stripAccents(key)
      if (!(d in deaccentIndex)) deaccentIndex[d] = key
    }
  }
  return deaccentIndex
}

export function lookupWord(raw: string): (DictEntry & { key: string }) | null {
  const clean = raw.trim().replace(/^(el|la|los|las|un|una)\s+/i, "").toLowerCase()

  // 命中词条后返回；若查的是阴性形容词形式，则返回阴性拼写 + 阴性冠词
  const resolve = (key: string): (DictEntry & { key: string }) => {
    const entry = DICT[key]
    if (entry.feminine && stripAccents(clean) === stripAccents(entry.feminine)) {
      return { ...entry, key: entry.feminine, article: "la" }
    }
    return { ...entry, key }
  }

  // 1. 精确匹配
  if (DICT[clean]) return resolve(clean)

  // 2. 词形还原 + 单词匹配
  for (const w of lemmatize(clean)) {
    if (DICT[w]) return resolve(w)
  }

  // 3. 去重音兜底匹配（漏重音：ojala→ojalá、rapidamente→rápidamente）
  const idx = getDeaccentIndex()
  const dClean = stripAccents(clean)
  if (idx[dClean]) return resolve(idx[dClean])
  for (const w of lemmatize(dClean)) {
    if (idx[w]) return resolve(idx[w])
  }

  return null
}

// 形容词阴阳性展示：双性形容词返回 { 阳性, 阴性 }，不变形形容词（grande/feliz 等）返回 null
export function getAdjectiveForms(raw: string): { masculine: string; feminine: string } | null {
  const entry = lookupWord(raw)
  if (!entry || entry.pos !== "ADJ" || !entry.feminine) return null
  const feminine = entry.feminine
  for (const key of Object.keys(DICT)) {
    if (DICT[key].pos === "ADJ" && DICT[key].feminine === feminine) {
      return { masculine: key, feminine }
    }
  }
  return { masculine: entry.key, feminine }
}

export default DICT